def sources(ref=None):
 if ref:
  names=subprocess.check_output(['git','ls-tree','-r','--name-only',ref,'--',str(fixtures.JAVA_PATH)],cwd=fixtures.ROOT,text=True).splitlines()
  result={'com/lastdom/game/'+Path(n).name:subprocess.check_output(['git','show',ref+':'+n],cwd=fixtures.ROOT,text=True) for n in names if n.endswith('.java')}
 else:result={'com/lastdom/game/'+p.name:p.read_text() for p in (fixtures.ROOT/fixtures.JAVA_PATH).glob('*.java')}
 result['com/lastdom/game/R.java']='package com.lastdom.game;public class R{public static class drawable{public static final int shelter_clean=1,shelter_full_scene=2;}}'
 return result

def main():
 with tempfile.TemporaryDirectory(prefix='last-signal-') as d:
  fixtures.PROBE=LEGACY;old=fixtures.run_version(Path(d),'online05',sources(BASE));blocks=[]
  for line in old.splitlines():
   if line=='SAVE':blocks.append([])
   elif line.startswith('VALUE:'):
    _,key,kind,value=line.split(':',3);value=base64.b64decode(value).decode();method={'Integer':'putInt','Boolean':'putBoolean','String':'putString'}[kind];literal=json.dumps(value,ensure_ascii=False) if kind=='String' else value;blocks[-1].append(f'e.{method}({json.dumps(key)}, {literal});')
  assert len(blocks)==2
  method=' static List<MemoryPreferences> legacy(){List<MemoryPreferences> result=new ArrayList<>();MemoryPreferences p;SharedPreferences.Editor e;'
  for block in blocks:method+='p=new MemoryPreferences();e=p.edit();'+''.join(block)+'e.commit();result.add(p);'
  method+='return result;}'
  fixtures.PROBE=PROBE.replace(' public static void main(String[]args){triggerAndMessages()',method+' public static void main(String[]args){triggerAndMessages()')
  print(fixtures.run_version(Path(d),'story10',sources()).strip())
if __name__=='__main__':main()
